& .am-head h1 { font-family: var(--font-sans); font-size: calc(28px * var(--am-scale, 1)); line-height: 1.3; font-weight: 650; letter-spacing: -0.025em; text-shadow: none; }
& .am-head h1::before { content: "// "; color: var(--accent); font-family: var(--font-mono); font-size: 0.72em; font-weight: 500; letter-spacing: -0.08em; }
& .am-panel { border-color: var(--frame-line); }
& .am-panel-id { border-radius: 5px; min-width: 24px; height: 24px; margin: 9px 0 9px 14px; font-size: calc(11px * var(--am-scale, 1)); font-weight: 600; font-family: var(--font-mono); }
& .am-panel-head { border-bottom-width: 1px; }
& .am-panel-head h2 { font-family: var(--font-sans); font-weight: 600; letter-spacing: -0.015em; }
& .am-md { line-height: 1.7; }
& .am-md h3 { color: var(--accent); font-weight: 600; }
& .am-md strong, & .am-intro strong { color: var(--priority); font-weight: 650; }
& .am-md a { text-underline-offset: 3px; text-decoration-thickness: 1px; }
& .am-md blockquote { border-inline-start: 2px solid var(--accent); }
& .am-md th { color: var(--accent); font-weight: 600; }
& .am-kv { border-color: var(--line); border-radius: var(--radius); overflow: hidden; }
& .am-callout { border-radius: 6px; }
& .am-callout--err { border-inline-start-color: var(--priority); }
& .am-callout--err .am-callout-title { color: var(--priority); }
@media (max-width: 760px) { & .am-head h1 { font-size: calc(24px * var(--am-scale, 1)); } }
/* Neon depth layer */
& .am-head { border-inline-start: 2px solid var(--neon-cyan); padding-inline-start: 14px; }
& .am-head h1 { color: var(--title-1); text-shadow: 0 0 12px var(--neon-glow); }
& .am-head h1::before { color: var(--title-2); text-shadow: 0 0 9px var(--neon-glow); }
& .am-panel { position: relative; border-color: var(--frame-line); border-top-color: color-mix(in srgb, var(--frame-amber) 55%, var(--frame-line)); }
& .am-panel::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 1.5px; background: linear-gradient(100deg, var(--frame-amber), var(--frame-gold) 65%, transparent); box-shadow: 0 0 8px var(--frame-glow); opacity: 0.62; pointer-events: none; }
& .am-panel-head { background: linear-gradient(110deg, var(--frame-wash), transparent 78%); }
& .am-panel-head h2 { color: var(--title-2); }
& .am-panel-id { border: 1px solid color-mix(in srgb, var(--frame-amber) 42%, transparent); box-shadow: 0 0 6px var(--frame-halo); }
& .am-md h1 { color: var(--title-1); }
& .am-md h2 { color: var(--title-2); }
& .am-md h3 { color: var(--title-3); }
& .am-md h4 { color: var(--title-4); }
& .am-md h5 { color: var(--title-5); font-size: calc(12px * var(--am-scale, 1)); line-height: 1.5; margin: 14px 0 6px; }
& .am-md h6 { color: var(--title-6); font-size: calc(12px * var(--am-scale, 1)); line-height: 1.5; margin: 14px 0 6px; }
& .am-md h3::before { content: "> "; color: var(--neon-cyan); font-family: var(--font-mono); }
@media print { & .am-head h1 { text-shadow: none; } & .am-panel { box-shadow: none; } & .am-panel::before { display: none; } }
/* City haze background */
& body { background-color: var(--bg); background-image: radial-gradient(ellipse at 14% 3%, var(--scene-blue), transparent 56%), radial-gradient(ellipse at 91% 34%, var(--scene-cyan), transparent 48%), radial-gradient(ellipse at 85% 94%, var(--scene-amber), transparent 43%), linear-gradient(150deg, var(--scene-fog), transparent 58%); background-attachment: fixed; background-repeat: no-repeat; min-height: 100vh; }
@media print { & body { background: var(--paper); min-height: auto; } }
/* Candidate long-document navigation spacing */
& .am-panel { scroll-margin-top: 80px; }
@media (max-width: 760px) { & .am-head { margin-top: 60px; } & .am-panel { scroll-margin-top: 110px; } }
